// @generated by:gauntlet run:godseye-audit-r1-r4
import { randomUUID } from "node:crypto";
import type { RegisterJobDefinitionInput } from "@godseye/contracts";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type JobsFixture, jobsFixture } from "./jobs-helpers.js";

describe("T18 immutable authority while job effects remain unresolved (audit R1)", () => {
  let fixture: JobsFixture;
  beforeEach(async () => {
    fixture = await jobsFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });

  it("refuses to relax an unknown protected effect into an automatic retry", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    fixture.handler.script = async () => ({ status: "unknown" });
    const run = await fixture.trigger(definition.id, 0, "audit-unknown-0001");
    await fixture.work();

    await expect(fixture.register({ effectPolicy: "idempotent" })).rejects.toMatchObject({
      code: "JOB_DEFINITION_BUSY",
      status: 409,
    });
    const restarted = fixture.build();
    await restarted.jobs.tick();

    expect(await fixture.state(run.id)).toMatchObject({ state: "unknown", attempt: 1 });
    expect(fixture.handler.calls).toHaveLength(1);
    expect((await restarted.jobs.overview(fixture.freshOwner())).definitions[0]).toMatchObject({
      revision: definition.revision,
      effectPolicy: "protected",
      hash: definition.hash,
    });
  });

  it("keeps identical registration idempotent while a protected effect is unknown", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    fixture.handler.script = async () => ({ status: "unknown" });
    await fixture.trigger(definition.id, 0, "audit-identical-001");
    await fixture.work();

    expect(await fixture.register({ effectPolicy: "protected" })).toMatchObject({
      id: definition.id,
      revision: definition.revision,
      hash: definition.hash,
    });
  });

  it.each<{ label: string; changed: Partial<RegisterJobDefinitionInput> }>([
    { label: "handler", changed: { handler: "fixture.other" } },
    { label: "policy", changed: { effectPolicy: "read_only" } },
    {
      label: "limits",
      changed: {
        limits: { maxConcurrent: 1, maxAttempts: 5, timeoutSeconds: 30, retentionDays: 7 },
      },
    },
  ])(
    "refuses a changed $label while a queued run still binds the definition",
    async ({ changed }) => {
      const definition = await fixture.register();
      const run = await fixture.trigger(definition.id, 0, `audit-queued-${randomUUID()}`);

      await expect(fixture.register(changed)).rejects.toMatchObject({
        code: "JOB_DEFINITION_BUSY",
        status: 409,
      });

      expect((await fixture.state(run.id)).state).toBe("queued");
      expect((await fixture.jobs().overview(fixture.freshOwner())).definitions[0]).toMatchObject({
        revision: definition.revision,
        hash: definition.hash,
      });
    },
  );

  it("allows the next definition only after owner reconciliation settles the old effect", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    fixture.handler.script = async () => ({ status: "unknown" });
    fixture.handler.probe = async () => ({ status: "succeeded", evidenceRef: "fixture:observed" });
    const run = await fixture.trigger(definition.id, 0, "audit-settled-0001");
    await fixture.work();
    await fixture
      .jobs()
      .reconcileRun(
        fixture.freshOwner(),
        run.id,
        { expectedState: "unknown", resolution: "probe_read_only", evidenceRef: "audit:receipt-1" },
        randomUUID(),
      );

    expect(await fixture.register({ effectPolicy: "idempotent" })).toMatchObject({
      id: definition.id,
      revision: definition.revision + 1,
      effectPolicy: "idempotent",
    });
    expect(await fixture.state(run.id)).toMatchObject({ state: "succeeded", attempt: 1 });
    expect(fixture.handler.calls).toHaveLength(1);
  });
});
